update _animal 
set category_code = #{category_code}, category_etc_value = #{category_etc_value}, animal_name = #{animal_name}, 
  animal_color = #{animal_color}, animal_gender = #{animal_gender}, animal_neuter = #{animal_neuter}, 
   animal_age = #{animal_age}, animal_weight = #{animal_weight}, animal_regnum = #{animal_regnum}, 
    animal_act = #{animal_act}, animal_social = #{animal_social}, animal_etc = #{animal_etc}, adpt_member = #{adpt_member} 
     where animal_id = #{animal_id}

update _animal 
set animal_status = #{animal_status}, animal_reason = #{animal_reason} 
where animal_id = #{animal_id}

update _adpt 
set adpt_intro = #{adpt_intro}, adpt_etc = #{adpt_etc}, adpt_status = #{adpt_status} 
where animal_id = #{animal_id}

update _adpt 
set adpt_status = #{adpt_status} 
where animal_id = #{animal_id} and adpt_id = #{adpt_id}

